# Build HE-style prompts from MBPP problems: signature from reference, docstring from description + example.
import ast, re
INSTR = "\n\nWrite a complete, self-contained Python 3 solution. Put your final code in a single " + '`'*3 + "python block at the end of your answer."
def split_problem(q):
    txt = q['problem']
    assert txt.endswith(INSTR), q['id']
    body = txt[:-len(INSTR)]
    desc, _, test = body.partition('\nYour code should pass this test:\n')
    return desc.strip(), test.strip()

bad = []
info = {}
for q in mbpp:
    desc, test = split_problem(q)
    try:
        tree = ast.parse(q['reference'])
    except Exception as e:
        bad.append((q['id'], 'refparse')); continue
    fdefs = [n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef) and n.name == q['entry_point']]
    if not fdefs:
        bad.append((q['id'], 'nodef')); continue
    fd = fdefs[0]
    try:
        tt = ast.parse(test)
    except Exception:
        bad.append((q['id'], 'testparse')); continue
    info[q['id']] = dict(desc=desc, test=test, fd=fd, ref=q['reference'])
