# Build HE-style prompt texts (typed where inferable) for all MBPP problems; inspect two.
def infer_type(v, used):
    if isinstance(v, bool): return 'bool'
    if isinstance(v, int): return 'int'
    if isinstance(v, float): return 'float'
    if isinstance(v, str): return 'str'
    if isinstance(v, (list, tuple, set, dict)):
        cont = {list: 'List', tuple: 'Tuple', set: 'Set', dict: 'Dict'}[type(v)]
        used.add(cont)
        if isinstance(v, dict):
            if not v: return 'Dict'
            kt = {infer_type(k, used) for k in v}; vt = {infer_type(x, used) for x in v.values()}
            if len(kt) == 1 and len(vt) == 1 and None not in kt | vt:
                return f'Dict[{kt.pop()}, {vt.pop()}]'
            return 'Dict'
        if not v: return cont
        ts = {infer_type(x, used) for x in v}
        if None in ts: return None
        if len(ts) == 1:
            t = ts.pop()
            return f'Tuple[{t}, ...]' if cont == 'Tuple' else f'{cont}[{t}]'
        if cont == 'Tuple' and len(v) <= 4:
            return 'Tuple[' + ', '.join(infer_type(x, used) for x in v) + ']'
        return cont
    return None

def docline(desc):
    d = re.sub(r'^Write (a|an) (python |Python )?(function|program|lambda function)( to| that| which)?\s*', '', desc).strip()
    if not d: d = desc
    return d[0].upper() + d[1:] if d else d

def he_prompt(qid, typed):
    q = mbpp[ids.index(qid)]; d = info[qid]; name = q['entry_point']
    fd = d['fd']; params = [a.arg for a in fd.args.args]
    t = ast.parse(d['test']).body[0]
    call = call_in_test(d['test'], name)
    example = None
    if isinstance(t, ast.Assert):
        tt = t.test
        if isinstance(tt, ast.Compare) and len(tt.ops) == 1 and isinstance(tt.ops[0], ast.Eq) and tt.left is call:
            example = (ast.get_source_segment(d['test'], call), ast.get_source_segment(d['test'], tt.comparators[0]))
        elif tt is call:
            example = (ast.get_source_segment(d['test'], call), 'True')
        elif isinstance(tt, ast.UnaryOp) and isinstance(tt.op, ast.Not) and tt.operand is call:
            example = (ast.get_source_segment(d['test'], call), 'False')
    sig_types, ret_t, used = None, None, set()
    if typed and example and call is not None and len(call.args) == len(params) and not call.keywords:
        try:
            vals = [ast.literal_eval(a) for a in call.args]
            ts = [infer_type(v, used) for v in vals]
            rv = ast.literal_eval(example[1]); rt = infer_type(rv, used)
            if None not in ts and rt is not None:
                sig_types, ret_t = ts, rt
        except Exception:
            pass
    if sig_types:
        sig = f"def {name}(" + ', '.join(f'{p}: {t}' for p, t in zip(params, sig_types)) + f") -> {ret_t}:"
        head = ('from typing import ' + ', '.join(sorted(used)) + '\n\n\n') if used else ''
    else:
        sig = f"def {name}(" + ', '.join(params) + "):"; head = ''
    doc = '    """ ' + docline(d['desc'])
    if example:
        doc += f"\n    >>> {example[0]}\n    {example[1]}\n    \"\"\""
    else:
        doc += f"\n    Example: {d['test']}\n    \"\"\""
    code = head + sig + '\n' + doc + '\n'
    return '`'*3 + 'python\n' + code + '`'*3 + INSTR, bool(sig_types)

